import React, { useState } from "react";
import { Dialog, DialogActions, DialogContent, DialogTitle, Button, Box } from "@mui/material";

const MediaDialog = ({ open, handleClose, handleSend, file }) => {
  return (
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle>Preview Media</DialogTitle>
      <DialogContent>
        <Box sx={{ width: "100%", display: "flex", justifyContent: "center" }}>
          {file && file.type.startsWith("image/") && (
            <img src={URL.createObjectURL(file)} alt="Preview" style={{ maxWidth: "100%", maxHeight: "400px" }} />
          )}
          {file && file.type.startsWith("video/") && (
            <video controls style={{ maxWidth: "100%", maxHeight: "400px" }}>
              <source src={URL.createObjectURL(file)} type={file.type} />
              Your browser does not support the video tag.
            </video>
          )}
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} color="secondary">Cancel</Button>
        <Button onClick={handleSend} color="primary">Send</Button>
      </DialogActions>
    </Dialog>
  );
};

export default MediaDialog;
